-- A database at PRAGMA user_version 9 (palette-references plan session 2): a project "Old layers"
-- with five patched heads (hex-1..3, spot-1..2), a group "front-wash" of hex-1 and hex-2, the value
-- palettes "Red", "Red white" and per-fixture "DSR Focus", the FX palette "Chase", and the Looks "Warm"
-- (hex-1 colour) and "Bright" (hex-1 dimmer). Each cue holds one palette layer: "Plain", "Own row"
-- (hex-1's own white row), "Per-fixture" (no targets) and "Under an intensity Look" convert; "Half
-- amount", "Additive", "Stomp", "Timed", "Disabled", "Foreign mask", "Under a Look" and "FX palette"
-- stay. Its schema is a v9 desk's after palette-references session 1. Frozen: never regenerate it from
-- a later commit. The desk's accounts and sessions are left out.

CREATE TABLE busk_banks (id INTEGER PRIMARY KEY AUTOINCREMENT, column_id INT NOT NULL, sort_order INT NOT NULL, "name" VARCHAR(255) NOT NULL, solo BOOLEAN DEFAULT 0 NOT NULL, flow VARCHAR(16) DEFAULT 'WRAP' NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_banks_column_id__id FOREIGN KEY (column_id) REFERENCES busk_columns(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_banks_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_banks_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_columns (id INTEGER PRIMARY KEY AUTOINCREMENT, page_id INT NOT NULL, "row" INT NOT NULL, sort_order INT NOT NULL, width INT NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_columns_page_id__id FOREIGN KEY (page_id) REFERENCES busk_pages(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_columns_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_row CHECK ("row" BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_width CHECK (width BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_pads (id INTEGER PRIMARY KEY AUTOINCREMENT, bank_id INT NOT NULL, sort_order INT NOT NULL, palette_id INT NULL, look_id INT NULL, cue_id INT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_pads_bank_id__id FOREIGN KEY (bank_id) REFERENCES busk_banks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_palette_id__id FOREIGN KEY (palette_id) REFERENCES palettes(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_look_id__id FOREIGN KEY (look_id) REFERENCES looks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_cue_id__id FOREIGN KEY (cue_id) REFERENCES cues(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_pads_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_pads_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT busk_pad_exactly_one_ref CHECK (((palette_id IS NOT NULL) AND (look_id IS NULL) AND (cue_id IS NULL)) OR ((palette_id IS NULL) AND (look_id IS NOT NULL) AND (cue_id IS NULL)) OR ((palette_id IS NULL) AND (look_id IS NULL) AND (cue_id IS NOT NULL))));
CREATE TABLE busk_pages (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INT NOT NULL, "name" VARCHAR(255) NOT NULL, sort_order INT DEFAULT 0 NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_pages_project_id__id FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_pages_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_pages_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_rig_rows (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INT NOT NULL, "name" VARCHAR(64) NOT NULL, sort_order INT DEFAULT 0 NOT NULL, uuid BINARY(16) NOT NULL, flow VARCHAR(16) DEFAULT 'SCROLL' NOT NULL, width INT DEFAULT 12 NOT NULL, CONSTRAINT fk_busk_rig_rows_project_id__id FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_rig_rows_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_rig_rows_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_rig_rows_signed_integer_width CHECK (width BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_rig_tiles (id INTEGER PRIMARY KEY AUTOINCREMENT, row_id INT NOT NULL, sort_order INT NOT NULL, uuid BINARY(16) NOT NULL, group_id INT NULL, patch_id INT NULL, element_key VARCHAR(128) NULL, cell_mode VARCHAR(16) DEFAULT 'PIPS' NOT NULL, cell_split INT NULL, label VARCHAR(64) NULL, CONSTRAINT fk_busk_rig_tiles_row_id__id FOREIGN KEY (row_id) REFERENCES busk_rig_rows(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_rig_tiles_group_id__id FOREIGN KEY (group_id) REFERENCES fixture_groups(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_rig_tiles_patch_id__id FOREIGN KEY (patch_id) REFERENCES fixture_patches(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_rig_tiles_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_rig_tiles_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_rig_tiles_signed_integer_cell_split CHECK (cell_split BETWEEN -2147483648 AND 2147483647), CONSTRAINT busk_rig_tile_exactly_one_ref CHECK (((group_id IS NOT NULL) AND (patch_id IS NULL)) OR ((group_id IS NULL) AND (patch_id IS NOT NULL))));
