CREATE TABLE cloud_identity_links (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INT NOT NULL, cloud_account_id TEXT NOT NULL, email TEXT NOT NULL, linked_at TEXT NOT NULL, linked_via VARCHAR(16) NOT NULL, CONSTRAINT fk_cloud_identity_links_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT chk_cloud_identity_links_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647));
CREATE TABLE control_surface_bindings (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INT NOT NULL, device_type_key VARCHAR(100) NOT NULL, control_id VARCHAR(100) NOT NULL, bank VARCHAR(100) NULL, target_type VARCHAR(50) NOT NULL, target_payload TEXT NOT NULL, takeover_policy VARCHAR(30) NULL, sort_order INT DEFAULT 0 NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_control_surface_bindings_project_id__id FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_control_surface_bindings_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_control_surface_bindings_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
CREATE TABLE cue_ad_hoc_fx (id INTEGER PRIMARY KEY AUTOINCREMENT, cue_id INT NOT NULL, target_type VARCHAR(50) NOT NULL, target_key TEXT NOT NULL, fx_type VARCHAR(255) NOT NULL, family VARCHAR(50) NOT NULL, "attribute" VARCHAR(255) NULL, "cycle" DOUBLE PRECISION NOT NULL, blend_mode VARCHAR(50) NOT NULL, spread_order VARCHAR(50) NOT NULL, phase_offset DOUBLE PRECISION DEFAULT 0.0 NOT NULL, element_mode VARCHAR(50) NULL, element_filter VARCHAR(50) NULL, timing VARCHAR(8) NULL, parameters TEXT NOT NULL, delay BIGINT NULL, "interval" BIGINT NULL, random_window BIGINT NULL, sort_order INT DEFAULT 0 NOT NULL, speed_master_uuid BINARY(16) NULL, rate_speed_master_uuid BINARY(16) NULL, seconds BOOLEAN DEFAULT 0 NOT NULL, amount DOUBLE PRECISION DEFAULT 1.0 NOT NULL, direction VARCHAR(16) DEFAULT 'FORWARD' NOT NULL, runs INT NULL, spread DOUBLE PRECISION DEFAULT 1.0 NOT NULL, spread_wings INT DEFAULT 1 NOT NULL, spread_segments INT DEFAULT 1 NOT NULL, spread_parts INT DEFAULT 0 NOT NULL, spread_unit VARCHAR(8) NULL, uuid BINARY(16) NOT NULL, run_uuid BINARY(16) NULL, CONSTRAINT fk_cue_ad_hoc_fx_cue_id__id FOREIGN KEY (cue_id) REFERENCES cues(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_cue_ad_hoc_fx_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_cue_ad_hoc_fx_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_cue_ad_hoc_fx_signed_integer_runs CHECK (runs BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_cue_ad_hoc_fx_signed_integer_spread_wings CHECK (spread_wings BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_cue_ad_hoc_fx_signed_integer_spread_segments CHECK (spread_segments BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_cue_ad_hoc_fx_signed_integer_spread_parts CHECK (spread_parts BETWEEN -2147483648 AND 2147483647));
CREATE TABLE cue_attribute_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, cue_id INT NOT NULL, target_type VARCHAR(50) NOT NULL, target_key VARCHAR(255) NOT NULL, "attribute" VARCHAR(255) NOT NULL, "value" TEXT NOT NULL, fade_duration BIGINT NULL, sort_order INT DEFAULT 0 NOT NULL, uuid BINARY(16) NOT NULL, palette_uuid BINARY(16) NULL, CONSTRAINT fk_cue_attribute_assignments_cue_id__id FOREIGN KEY (cue_id) REFERENCES cues(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_cue_attribute_assignments_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_cue_attribute_assignments_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
